#include "stdlib/stats/base/ndarray/snanmskmin.h"
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>
#include <stdint.h>

#define NAME "snanmskmin"
#define ITERATIONS 1000000
#define REPEATS 3

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total );
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmarks results.
*
* @param iterations   number of iterations
* @param elapsed      elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %g\n", elapsed );
	printf( "  rate: %g\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time to resolve high precision timing.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec / 1.0e6;
}

/**
* Generates a random number.
*
* @return random number
*/
static float rand_float( void ) {
	float r = (float)rand() / (float)RAND_MAX;
	if ( r > 0.8f ) {
		return 0.0f / 0.0f;
	}
	return ( r * 20.0f ) - 10.0f;
}

/**
* Generates a random mask value.
*
* @return random mask value
*/
static uint8_t rand_mask( void ) {
	float r = (float)rand() / (float)RAND_MAX;
	if ( r < 0.2f ) {
		return 1;
	}
	return 0;
}

/**
* Runs a benchmark.
*
* @param iterations   number of iterations
* @param len          array length
* @return             elapsed time in seconds
*/
static double benchmark( int iterations, int len ) {
	double elapsed;
	double t;
	float *x;
	uint8_t *mask;
	int i;
	float v;

	x = (float *)malloc( len * sizeof(float) );
	if ( x == NULL ) {
		printf( "unable to allocate memory\n" );
		exit( 1 );
	}
	mask = (uint8_t *)malloc( len * sizeof(uint8_t) );
	if ( mask == NULL ) {
		printf( "unable to allocate memory\n" );
		exit( 1 );
	}
	for ( i = 0; i < len; i++ ) {
		x[ i ] = rand_float();
		mask[ i ] = rand_mask();
	}

	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		x[ i % len ] = (float)i;
		v = stdlib_ndarray_snanmskmin( len, x, 1, 0, mask, 1, 0 );
		if ( v != v && v == v ) { // Should never happen unless compiler optimizes this out incorrectly, just to use v
			printf( "unexpected result\n" );
		}
	}
	elapsed = tic() - t;

	if ( v != v && v == v ) {
		printf( "unexpected result\n" );
	}
	free( x );
	free( mask );

	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int count;
	int iter;
	int len;
	int i;
	int j;

	// Use the current time to seed the random number generator:
	srand( time( NULL ) );

	print_version();
	count = 0;
	for ( i = 1; i <= 6; i++ ) {
		len = pow( 10, i );
		iter = ITERATIONS / pow( 10, i - 1 );
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s:len=%d\n", NAME, len );
			elapsed = benchmark( iter, len );
			print_results( iter, elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	print_summary( count, count );
	return 0;
}
